// ─── File: IdempotencyDemo.java ───
// Runnable demo contrasting idempotent (GET/PUT/DELETE) vs non-idempotent (POST).
package com.bank.idempotency;

import java.math.BigDecimal;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.*;

public class IdempotencyDemo {

    private static final Logger log = Logger.getLogger("Idempotency");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountResource resource = new AccountResource();
        resource.seed("SAV2001", new BigDecimal("1000000"));
        resource.seed("CUR3001", new BigDecimal("250000"));
        RetryingClient client = new RetryingClient(resource);

        // GET — idempotent: two reads leave state unchanged.
        client.callTwice("GET balance SAV2001", () -> resource.getBalance("SAV2001"));

        // PUT — idempotent: replacing the address twice leaves one address.
        client.callTwice("PUT address SAV2001", () -> {
            resource.putAddress("SAV2001", "12 MG Road, Pune");
            return resource.getAddress("SAV2001");
        });

        // DELETE — idempotent: deleting twice leaves it deleted.
        client.callTwice("DELETE standing-instruction SAV2001", () -> {
            resource.deleteStandingInstruction("SAV2001");
            return resource.hasStandingInstruction("SAV2001") ? "present" : "absent";
        });

        // POST transfer WITHOUT idempotency key — double-applies on retry (BAD).
        log.warning("POST transfer without key (naive):");
        client.callTwice("POST transfer 50000", () -> {
            resource.transferNaive("SAV2001", "CUR3001", new BigDecimal("50000"));
            return "CUR3001=" + resource.getBalance("CUR3001");
        });

        // POST transfer WITH idempotency key — safe on retry (GOOD).
        log.info("POST transfer with idempotency key (safe):");
        client.callTwice("POST transfer 20000 key=K-1", () ->
                resource.transferIdempotent("SAV2001", "CUR3001",
                        new BigDecimal("20000"), "K-1"));
    }
}

// ─── resource/AccountResource.java ───
class AccountResource {
    private final Map<String, BigDecimal> balances = new ConcurrentHashMap<>();
    private final Map<String, String> addresses = new ConcurrentHashMap<>();
    private final Map<String, Boolean> standingInstr = new ConcurrentHashMap<>();
    private final IdempotencyStore idemStore = new IdempotencyStore();

    void seed(String id, BigDecimal b) {
        balances.put(id, b); standingInstr.put(id, Boolean.TRUE);
    }
    BigDecimal getBalance(String id) { return balances.get(id); }

    // PUT = full replacement → idempotent
    void putAddress(String id, String address) { addresses.put(id, address); }
    String getAddress(String id) { return addresses.get(id); }

    // DELETE → idempotent (gone stays gone)
    void deleteStandingInstruction(String id) { standingInstr.remove(id); }
    boolean hasStandingInstruction(String id) { return standingInstr.containsKey(id); }

    // POST transfer, NAIVE: not idempotent, double-applies on retry
    void transferNaive(String from, String to, BigDecimal amt) {
        balances.merge(from, amt.negate(), BigDecimal::add);
        balances.merge(to, amt, BigDecimal::add);
    }

    // POST transfer, idempotency key makes it safe to retry
    String transferIdempotent(String from, String to, BigDecimal amt, String key) {
        String cached = idemStore.getResult(key);
        if (cached != null) return cached + " (returned stored result)";
        balances.merge(from, amt.negate(), BigDecimal::add);
        balances.merge(to, amt, BigDecimal::add);
        String result = "CUR3001=" + balances.get(to);
        idemStore.store(key, result);
        return result;
    }
}

// ─── store/IdempotencyStore.java ───
class IdempotencyStore {
    private final Map<String, String> keyToResult = new ConcurrentHashMap<>();
    String getResult(String key) { return keyToResult.get(key); }
    void store(String key, String result) { keyToResult.putIfAbsent(key, result); }
}

// ─── client/RetryingClient.java ───
class RetryingClient {
    private static final Logger log = Logger.getLogger("Idempotency");
    private final AccountResource resource;
    RetryingClient(AccountResource resource) { this.resource = resource; }
    // Simulates a client/proxy that retries the SAME request once.
    void callTwice(String label, java.util.function.Supplier<Object> call) {
        Object first = call.get();
        Object second = call.get();   // the retry
        log.info(() -> label + " → first=" + first + " | retry=" + second);
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
